const hoy = $now.toFormat('yyyy-LL-dd');
const out = [];
for (const it of $input.all()) {
  const l = it.json; if (!l || !l.ID_Lead) continue;
  if (l.Estado !== 'contactado') continue;
  if (String(l.Fecha_Siguiente_Paso).slice(0,10) !== hoy) continue;
  if ((Number(l.Num_Toques)||0) >= 9) continue;
  if (!String(l.Correo||'').includes('@')) continue;
  const toque = (Number(l.Num_Toques)||0) < 3 ? 'prueba_social' : 'breakup';
  const system = [
'<identidad>Agente de ACCES GROUP (Ricardo Varela). Seguimiento con valor, sin presion, sin culpa, sin inventar. Regla 70/30.</identidad>',
'<tarea>Redactar el siguiente toque de correo de la cadencia 3x3x30. PROHIBIDO "solo dando seguimiento", "ya lo revisaste?". Cada toque aporta valor/evidencia/pregunta util.</tarea>',
'<tipo>prueba_social: aportar prueba social real del portafolio ACCES sin exagerar (clientes de alimentos: Bafar, Yakult, Verde Valle, Patron, Sesajal) y reencuadrar el dolor del sector. breakup: correo de cierre de ciclo, elegante, deja puerta abierta a reactivacion.</tipo>',
'<reglas>Espanol de negocio, max ~100 palabras, 1 CTA suave (llamada 20 min), sin firma, HTML simple. Si es por precio, ofrece reactivacion por etapas. Propon nueva fecha_siguiente_paso (~5-7 dias) salvo breakup (entonces nurturing).</reglas>',
'<salida>SOLO este JSON sin ``` : {"asunto":"","cuerpo_html":"","cierra_ciclo":false,"fecha_siguiente_paso":"YYYY-MM-DD","razon":""}</salida>'
  ].join('\n');
  const user = `Fecha hoy: ${hoy}\nLead: ${l.Empresa} — ${l.Contacto} (${l.Cargo}) | Micro-ICP: ${l.Micro_ICP}\nTrigger: ${l.Trigger_Regulatorio} | Toques: ${l.Num_Toques} | Tipo de toque: ${toque}\nUltimo asunto: ${l.Asunto}\nRedacta el toque. Devuelve solo el JSON.`;
  out.push({ json: { ...l, tipo_toque: toque, system, user, hoy } });
}
return out;

const FIRMA = '<br><br><table cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;font-size:13px;color:#333"><tr><td style="padding-top:12px;border-top:2px solid #0a3d62"><strong style="color:#0a3d62">Ricardo Varela</strong><br><span style="color:#555">ACCES GROUP</span><br><a href="mailto:rvarela@accesgroup.com.mx" style="color:#0a3d62">rvarela@accesgroup.com.mx</a></td></tr></table>';
const resp=$json; let text='';
try { const _b = resp.content || (resp.body && resp.body.content) || []; const _t = _b.find(x => x && x.type === 'text'); text = _t ? _t.text : '{}'; } catch(e){ text = '{}'; }
text = text.replace(/^```json/i,'').replace(/```$/,'').trim();
const d = JSON.parse(text);
const l = $('Filtrar vencidos hoy').item.json;
d.cuerpo_final = (d.cuerpo_html||'') + FIRMA;
d.nuevo_estado = d.cierra_ciclo ? 'nurturing' : 'contactado';
return [{ json: { ...l, ...d } }];
